function parseDate(v){
  if(v===undefined||v===null||v==='') return null;
  const s=String(v).trim();
  let m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if(m){ const d=DateTime.fromObject({day:+m[1],month:+m[2],year:+m[3]},{zone:'Europe/Istanbul'}); return d.isValid?d.startOf('day'):null; }
  m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m){ const d=DateTime.fromObject({year:+m[1],month:+m[2],day:+m[3]},{zone:'Europe/Istanbul'}); return d.isValid?d.startOf('day'):null; }
  const d=DateTime.fromISO(s,{zone:'Europe/Istanbul'});
  return d.isValid?d.startOf('day'):null;
}
function num(v){
  if(v===undefined||v===null||v==='') return 0;
  let s=String(v).replace(/[^\d.,-]/g,'');
  if(s.indexOf(',')>-1 && s.indexOf('.')>-1){ s=s.replace(/\./g,'').replace(',', '.'); }
  else if(s.indexOf(',')>-1){ s=s.replace(',', '.'); }
  const n=parseFloat(s);
  return isNaN(n)?0:n;
}
function fmt(n){ return Number(n).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}); }

const items=$input.all();
const out=[];
const today=$now.setZone('Europe/Istanbul').startOf('day');
const todayStr=today.toFormat('dd.MM.yyyy');
const UPCOMING=3;

for(const it of items){
  const r=it.json;
  const durum=String(r.durum||'').trim().toLocaleLowerCase('tr-TR');
  if(durum==='ödendi'||durum==='odendi'||durum==='iptal'||durum==='kapandı'||durum==='kapandi') continue;
  if(!r.email) continue;
  const vade=parseDate(r.vade_tarihi);
  if(!vade) continue;

  const diff=Math.round(vade.diff(today,'days').days);
  const gecikme=-diff;

  let tier=null;
  if(diff===UPCOMING) tier='yaklasiyor';
  else if(diff===0) tier='bugun';
  else if(gecikme>=1 && gecikme<=7) tier='gecikti';
  else if(gecikme>7) tier='ciddi';
  else continue;

  if(String(r.son_hatirlatma_tarihi||'').trim()===todayStr) continue;

  const musteri=r.musteri||'Sayın Müşterimiz';
  const fatura=r.fatura_no||'';
  const pb=r.para_birimi||'TL';
  const tutar=r.tutar||'';
  const vadeStr=vade.toFormat('dd.MM.yyyy');

  let subject, body, yeniDurum=r.durum||'', severity='normal';
  if(tier==='yaklasiyor'){
    subject=`Hatırlatma: ${fatura} numaralı faturanızın vadesi yaklaşıyor`;
    body=`Sayın ${musteri},\n\n${fatura} numaralı, ${tutar} ${pb} tutarındaki faturanızın son ödeme tarihi ${vadeStr} (3 gün sonra).\n\nÖdemenizi daha önce ilettiyseniz bu mesajı dikkate almayınız.\n\nSaygılarımızla,\nMirFix Tahsilat`;
  } else if(tier==='bugun'){
    subject=`Bugün son ödeme günü — ${fatura} numaralı fatura`;
    body=`Sayın ${musteri},\n\n${fatura} numaralı, ${tutar} ${pb} tutarındaki faturanızın son ödeme tarihi bugün (${vadeStr}).\n\nÖdemenizi bugün iletmenizi rica ederiz.\n\nSaygılarımızla,\nMirFix Tahsilat`;
  } else if(tier==='gecikti'){
    subject=`Ödeme hatırlatması — ${fatura} (${gecikme} gün gecikti)`;
    body=`Sayın ${musteri},\n\n${fatura} numaralı, ${tutar} ${pb} tutarındaki faturanızın vadesi ${vadeStr} tarihinde dolmuştur ve ${gecikme} gündür ödenmemiştir.\n\nEn kısa sürede ödemenizi rica ederiz. Ödemeyi yaptıysanız lütfen bilgi veriniz.\n\nSaygılarımızla,\nMirFix Tahsilat`;
    yeniDurum='Gecikti'; severity='uyari';
  } else {
    subject=`ÖNEMLİ — ${fatura} numaralı fatura ${gecikme} gündür ödenmemiştir`;
    body=`Sayın ${musteri},\n\n${fatura} numaralı, ${tutar} ${pb} tutarındaki faturanızın vadesi ${vadeStr} tarihinde dolmuş olup ${gecikme} gündür ödenmemiştir.\n\nGecikmenin büyümemesi için lütfen acilen ödeme yapınız veya bizimle iletişime geçiniz.\n\nSaygılarımızla,\nMirFix Tahsilat`;
    yeniDurum='Gecikti'; severity='ciddi';
  }

  out.push({ json:{
    fatura_no:fatura, musteri, email:r.email, tutar, para_birimi:pb,
    vade_tarihi:vadeStr, gecikme_gun:gecikme>0?gecikme:0, tier, severity,
    email_subject:subject, email_body:body,
    yeni_durum:yeniDurum, yeni_son_hatirlatma:todayStr,
    yeni_hatirlatma_sayisi:(parseInt(r.hatirlatma_sayisi)||0)+1
  }});
}
return out;

const items=$input.all();
if(items.length===0) return [];
const toplam=items.reduce((a,i)=>a+(parseFloat(String(i.json.tutar).replace(/[^\d.,-]/g,'').replace(/\./g,'').replace(',', '.'))||0),0);
const lines=items.map(i=>`• ${i.json.fatura_no} — ${i.json.musteri} — ${i.json.tutar} ${i.json.para_birimi} — ${i.json.gecikme_gun} gün gecikme`);
const body=`Aşağıdaki faturalar 7 günden uzun süredir ödenmemiştir (ciddi gecikme):\n\n${lines.join('\n')}\n\nToplam ${items.length} fatura. Lütfen bizzat ilgilenin.`;
return [{ json:{ ekip_subject:`⚠️ ${items.length} fatura ciddi gecikmede`, ekip_body:body }}];
